-- 600 deterministic verified reviews with realistic rating skew, varied copy, moderation and helpful/report fixtures.


-- Helpful reactions: deterministic subset, idempotent by PK(review_id,user_id).
SELECT r.id,CONCAT('demo-customer-',1+MOD(r.id*3,20)),NOW()-INTERVAL MOD(r.id,20) DAY
FROM review r
WHERE r.order_line_id BETWEEN 900001 AND 900600 AND MOD(r.id,5)=0;

-- A small moderation queue; low ratings are more likely to be reported but reports remain rare.
SELECT r.id,CONCAT('demo-customer-',1+MOD(r.id*5,20)),
       CASE WHEN r.rating<=2 THEN 'Nội dung cần kiểm tra' ELSE 'Nghi ngờ spam/lặp nội dung' END,
       CASE WHEN MOD(r.id,3)=0 THEN 'RESOLVED' ELSE 'PENDING' END,
       NOW()-INTERVAL MOD(r.id,10) DAY
FROM review r
WHERE r.order_line_id BETWEEN 900001 AND 900600 AND MOD(r.id,41)=0;
